# tests/test_topological_sort.py

import pytest

from your_module import topological_sort


def _all_nodes(graph: dict) -> set:
    nodes = set(graph.keys())
    for neighbors in graph.values():
        nodes.update(neighbors)
    return nodes


def assert_valid_topological_order(graph: dict, order: list) -> None:
    """Assert every edge node -> neighbor appears in the correct order."""
    expected_nodes = _all_nodes(graph)

    assert set(order) == expected_nodes
    assert len(order) == len(expected_nodes)

    position = {node: index for index, node in enumerate(order)}

    for node, neighbors in graph.items():
        for neighbor in neighbors:
            assert position[node] < position[neighbor], (
                f"Expected {node!r} to appear before {neighbor!r} in {order!r}"
            )


def test_empty_graph_returns_empty_list():
    assert topological_sort({}) == []


def test_single_node_no_edges():
    graph = {"a": []}

    assert topological_sort(graph) == ["a"]


def test_linear_dag_happy_path():
    graph = {
        "a": ["b"],
        "b": ["c"],
        "c": [],
    }

    assert topological_sort(graph) == ["a", "b", "c"]


def test_branching_dag_returns_valid_topological_order():
    graph = {
        "a": ["b", "c"],
        "b": ["d"],
        "c": ["d"],
        "d": [],
    }

    order = topological_sort(graph)

    assert_valid_topological_order(graph, order)


def test_disconnected_components_return_all_nodes_once_and_respect_edges():
    graph = {
        "a": ["b"],
        "b": [],
        "c": ["d"],
        "d": [],
        "e": [],
    }

    order = topological_sort(graph)

    assert_valid_topological_order(graph, order)


def test_neighbor_not_defined_as_key_is_included_as_sink_node():
    graph = {
        "a": ["b"],
    }

    order = topological_sort(graph)

    assert order == ["a", "b"]
    assert_valid_topological_order(graph, order)


def test_duplicate_edges_do_not_duplicate_nodes_in_result():
    graph = {
        "a": ["b", "b"],
        "b": [],
    }

    order = topological_sort(graph)

    assert order == ["a", "b"]
    assert_valid_topological_order(graph, order)


def test_non_string_hashable_nodes_are_supported():
    graph = {
        1: [2, 3],
        2: [4],
        3: [4],
        4: [],
    }

    order = topological_sort(graph)

    assert_valid_topological_order(graph, order)


def test_tuple_neighbors_are_supported():
    graph = {
        "a": ("b", "c"),
        "b": (),
        "c": (),
    }

    order = topological_sort(graph)

    assert_valid_topological_order(graph, order)


def test_none_graph_raises_type_error():
    with pytest.raises(TypeError):
        topological_sort(None)


def test_non_mapping_input_raises_error():
    with pytest.raises((AttributeError, TypeError)):
        topological_sort(["a"])


def test_non_iterable_neighbors_raises_type_error():
    graph = {
        "a": None,
    }

    with pytest.raises(TypeError):
        topological_sort(graph)


def test_unhashable_neighbor_raises_type_error():
    graph = {
        "a": [["b"]],
    }

    with pytest.raises(TypeError):
        topological_sort(graph)


@pytest.mark.xfail(reason="Current implementation does not detect cycles.")
def test_cycle_raises_value_error():
    graph = {
        "a": ["b"],
        "b": ["a"],
    }

    with pytest.raises(ValueError):
        topological_sort(graph)
